rule content:
Depth(K, i+1) = Depth(K, i) + ?(K[i])
?(t) =
 1   if t ? {Punctuator("("), Punctuator("[")}
 -1  if t ? {Punctuator(")"), Punctuator("]")}
 0   otherwise

ExpSignEnd(T, i) =
 i+1  if i < |T| ? T[i] ? {"+", "-"}
 i    otherwise

ExpEnd(T, i) =
 DecRun(T, ExpSignEnd(T, i+1))  if i < |T| ? T[i] ? {"e", "E"}
 i                              otherwise

SensitiveTok(T, i, j, k) =
 []                    if k ? {StringLiteral, CharLiteral}
 SensitiveInSpan(T, i, j)  otherwise

UsingClause ? {
  UsingItem = ?module_path, name, alias_opt?,
  UsingList = ?module_path, specs?,
  UsingWildcard = ?module_path?
}

RecordMember ? {
  FieldDecl = ?attrs_opt, vis, boundary, name, type, init_opt, span, doc_opt?,
  MethodDecl = ?attrs_opt, vis, override, name, gen_params_opt, receiver, params, return_type_opt, contract_opt, body, span, doc_opt?,
  AssociatedTypeDecl = ?attrs_opt, vis, name, default_type_opt, span, doc_opt?
}

StateMember ? {
  StateFieldDecl = ?attrs_opt, vis, boundary, name, type, span, doc_opt?,
  StateMethodDecl = ?attrs_opt, vis, name, gen_params_opt, receiver, params, return_type_opt, contract_opt, body, span, doc_opt?,
  TransitionDecl = ?attrs_opt, vis, name, params, target_state, body, span, doc_opt?
}

ClassItem ? {
  ClassFieldDecl = ?attrs_opt, vis, boundary, name, type, span, doc_opt?,
  ClassMethodDecl = ?attrs_opt, vis, name, gen_params_opt, receiver, params, return_type_opt, contract_opt, body_opt, span, doc_opt?,
  AssociatedTypeDecl = ?attrs_opt, vis, name, type_opt, span, doc_opt?,
  AbstractStateDecl = ?attrs_opt, vis, name, fields, span, doc_opt?
}

HeapAllocatorInterface =
{
 ?"with_quota", `const`, [??, `size`, TypePrim("usize")?], TypeDynamic(`HeapAllocator`)?,
 ?"alloc_raw", `const`, [??, `count`, TypePrim("usize")?], TypeRawPtr(`mut`, TypePrim("u8"))?,
 ?"dealloc_raw", `const`, [??, `ptr`, TypeRawPtr(`mut`, TypePrim("u8"))?, ??, `count`, TypePrim("usize")?], TypePrim("()")?
}

SystemInterface =
{
 ?"exit", [??, `code`, TypePrim("i32")?], TypePrim("!")?,
 ?"get_env", [??, `key`, TypeString(`@View`)?], TypeString(`@View`)?,
 ?"run", [??, `command`, TypeString(`@View`)?], TypePrim("i32")?
}

ProcReturn(ret_opt) =
  { TypePrim("()")   if ret_opt = ?
    ret_opt          otherwise }

BodyReturnType(R) =
  { Result    if AsyncSig(R) = ?Out, In, Result, E?
    R         otherwise }

MovedArg(moved, e) =
  { MoveExpr(e)  if moved = true ? IsPlace(e)
    e            otherwise }

InnermostActiveRegion([?] ++ ?') =
  { r                         if ? r. r ? dom(?) ? RegionActiveType(?[r])
    InnermostActiveRegion(?')  otherwise }

ComputeDynamicContext(s, ancestors) =
  let enclosing_dynamic = FindInnermostDynamic(s, ancestors)
  match enclosing_dynamic {
    ?       ? false
    Some(_) ? true
  }

ArgType(p, a) =
  { ExprType(ConsumeArgExpr(ParamMode(p), ArgMoved(a), ArgExpr(a)))    if ParamMode(p) = `move`
    PlaceType(RefArgExpr(ArgExpr(a)))                                   if ParamMode(p) = ? }

PermWrap(T, B) =
  { { x ? TypePerm(p, T_x) | x ? T_x ? B }    if T = TypePerm(p, U)
    B                                      otherwise }

SuspendUniqueBind(?, init, T_b) =
  { SuspendUniquePath(?, ?, init)    if IsPlace(init) ? PermOf(ExprType(init)) = `unique` ? PermOf(T_b) = `const`
    ?                                otherwise }

IRSet(P) =
 {IRPath(P, m, P.assembly.emit_ir) | m ? EmitModuleList(P)}  if P.assembly.emit_ir ? {`ll`, `bc`}
 ?                                                      otherwise

TempCleanupIR(s) =
  { ?                                                   if k = 0
    SeqIRList([EmitDrop(T_k, v_k), ?, EmitDrop(T_1, v_1)])    otherwise }

**(Valid-Scalar)**
ScalarTypes = {"i8", "i16", "i32", "i64", "i128", "u8", "u16", "u32", "u64", "u128", "f16", "f32", "f64", "usize", "isize"}
? t ? ScalarTypes. ValidValue(TypePrim(t), bits) ? |bits| = PrimSize(t)

AssignParamRegs(params, conv) =
  let abi = ConventionLayout(SelectedTargetProfile, conv)
  let (int_regs, float_regs) = (abi.param_regs.int, abi.param_regs.float)
  let int_idx = 0, float_idx = 0, stack_offset = 0
  for each (mode, T) in params:
    if IsFloatType(T) ? float_idx < |float_regs|:
      assign float_regs[float_idx++]
    else if IsIntOrPtrType(T) ? int_idx < |int_regs|:
      assign int_regs[int_idx++]
    else:
      assign Stack(stack_offset)
      stack_offset += Align(sizeof(T), abi.stack_alignment)

LLVMPrim(name) =
 i8        if name ? {i8, u8}
 i16       if name ? {i16, u16}
 i32       if name ? {i32, u32}
 i64       if name ? {i64, u64}
 i128      if name ? {i128, u128}
 `half`    if name = f16
 `float`   if name = f32
 `double`  if name = f64
 i8        if name = `bool`
 i32       if name = `char`
 i64       if name ? {`usize`, `isize`}
 LLVMZST   if name ? {`()`, `!`}
 ?         otherwise

Lookup_B([?] ++ ??', x) =
  { ?[x]                if x ? dom(?)
    Lookup_B(??', x)     otherwise }

Update_B([?] ++ ??', x, info) =
  { [?[x ? info]] ++ ??'            if x ? dom(?)
    [?] ++ Update_B(??', x, info)   otherwise }

Lookup_?([?] ++ ?', k) =
  { Inactive             if k ? dom(?) ? ?[k] = Inactive
    Lookup_?(?', k)      otherwise }

JoinBindInfo(?s_1, mv_1, mut_1, resp_1?, ?s_2, mv_2, mut_2, resp_2?) =
  { ?JoinState(s_1, s_2), mv_1, mut_1, resp_1?   if mv_1 = mv_2 ? mut_1 = mut_2 ? resp_1 = resp_2
    ?                                            otherwise }

JoinScope_B(B_1, B_2) =
  { { x ? JoinBindInfo(B_1[x], B_2[x]) | x ? dom(B_1) }    if dom(B_1) = dom(B_2) ? ? x ? dom(B_1). JoinBindInfo(B_1[x], B_2[x]) ? ?
    ?                                                      otherwise }

Join_B(B_1 :: ??_1, B_2 :: ??_2) =
  { JoinScope_B(B_1, B_2) :: Join_B(??_1, ??_2)    if JoinScope_B(B_1, B_2) ? ? ? Join_B(??_1, ??_2) ? ?
    ?                                           otherwise }

PermAt(B, x) =
  { B[x]     if x ? dom(B)
    Active   otherwise }

JoinPerm(B_1 :: ?_1, B_2 :: ?_2) =
  { JoinScope_?(B_1, B_2) :: JoinPerm(?_1, ?_2)    if JoinScope_?(B_1, B_2) ? ? ? JoinPerm(?_1, ?_2) ? ?
    ?                                             otherwise }

FieldHead(FieldAccess(p, f)) =
  { f                if FieldHead(p) = ?
    FieldHead(p)     otherwise }

PlacePath(p) =
  { (PlaceRoot(p), [])               if p = Identifier(x)
    (PlaceRoot(p), FieldPathOf(p))   otherwise }

SuspendUniquePath(?, mode, p) =
  { SetTop(?, InactivateScope(Top(?), AncPaths(p)))    if mode = ? ? IsPlace(p) ? PermOf(ExprType(p)) = `unique`
    ?                                                 otherwise }

SuspendUnique(?, mode, e) =
  { SuspendUniquePath(?, mode, e)    if IsPlace(e)
    ?                               otherwise }

TempScope(e) =
  { BindInitScope(e)            if BindInitScope(e) ? ?
    StmtScope(EnclosingStmt(e)) otherwise }

TempOrder(e) =
  { TempOrderList(Children_LTR(e)) ++ [e]    if TempValue(e)
    TempOrderList(Children_LTR(e))           otherwise }

RegionBindName(?, alias_opt) =
  { alias_opt         if alias_opt ? ?
    FreshRegion(?)    otherwise }

ConsumeOnMove(??, e) =
  { Update_B(??, x, ?Moved, mv, mut, resp?)    if IsMoveExpr(e) ? x = PlaceRoot(MoveInner(e)) ? Lookup_B(??, x) = ?s, mv, mut, resp?
    ??                                         otherwise }

InnermostActiveRegion([?] ++ ?') =
  { r                          if ? r. r ? dom(?) ? RegionActiveType(?[r])
    InnermostActiveRegion(?')  otherwise }

Lookup_?([?S, M?] ++ ?_?, x) =
  { M[x]                if x ? dom(M)
    Lookup_?(?_?, x)    otherwise }

AllocTag([?tag, target?] ++ RS, r) =
  { tag              if target = r
    AllocTag(RS, r)  otherwise }

ClosureTargetProv(C, ?) =
  { FrameProv(?, ?)    if IsEscaping(C)
    StackProv(?_?)     otherwise }

FrameProv(?, ??_?, RS?) =
  { ?_Region(r)    if ? r. InnermostFrameRegion(??_?, RS?) = r
    StackProv(?_?) otherwise }

PopRegionScope(e :: es, scope) =
  { es                          if RegionScopeOf(e) = scope
    PopRegionScope(es, scope)   otherwise }

AddrOfBind(b) =
  { addr         if BindingValue(?, b) = Alias(addr)
    BindAddr(b)  if BindingValue(?, b) ? Alias(_) }

